pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, address(this).balance);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        c.withdrawAll(address(0x1234));
        uint256 balanceAfter = address(c).balance;
        if (caller == address(this)) {
            assertTrue(balanceAfter == 0, "balance should be zero after owner withdraw");
        } else {
            assertTrue(balanceAfter == balanceBefore, "balance should be unchanged by non-owner");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.deal(address(c), amount);
        uint256 initialBalance = address(c).balance;
        uint256 callerInitialBalance = caller.balance;

        vm.prank(caller);
        if (caller == address(this)) {
            c.withdrawAll(caller);
            uint256 callerFinalBalance = caller.balance;
            assertTrue(callerFinalBalance == callerInitialBalance + initialBalance);
        } else {
            (bool ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", caller));
            assertTrue(!ok);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address recipient, uint256 amount) public {
        // Bound amount to avoid overflow issues
        uint256 boundedAmount = bound(amount, 0, address(this).balance);

        // Fund the contract with some ether
        vm.deal(address(c), boundedAmount);

        // Record the contract balance before the call
        uint256 balanceBefore = address(c).balance;

        // Call withdrawAll as the owner (this contract is the owner per setUp)
        bool success;
        bytes memory data = abi.encodeWithSignature("withdrawAll(address)", recipient);
        (success, ) = address(c).call(data);

        // The rule: if the call succeeded, the contract balance must be zero
        // (since all funds are transferred out)
        assertTrue(!success || address(c).balance == 0);
    }
}

