// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(this));

        // Fund the contract
        vm.deal(address(c), amount);

        uint256 recipientBalanceBefore = recipient.balance;

        // Call withdrawAll
        c.withdrawAll(recipient);

        uint256 recipientBalanceAfter = recipient.balance;

        // General rule: the recipient's balance increases by exactly the contract's previous balance
        assertTrue(recipientBalanceAfter - recipientBalanceBefore == amount);
    }
}
